    public static void main (String[] args)
        throws Exception
    {
        logger.info("infer.Main start");
        final int imgsz = 1984;

        //final String imgName = "hove.png"; // 2520 x 1984
        final String imgName = "allegretto.png"; // 2520 x 2183
        //final String imgName = "allegretto-resized.jpg"; // 1984 x 1984
        final File imageFile = new File(imgName);
        final BufferedImage orgImage = ImageIO.read(imageFile);
        final double orgWidth = orgImage.getWidth();
        final double orgHeight = orgImage.getHeight();

        final double wRatio = orgWidth / imgsz;
        final double hRatio = orgHeight / imgsz;

        final NativeImageLoader loader = new NativeImageLoader(
                imgsz,
                imgsz,
                3,
                new ColorConversionTransform(COLOR_BGR2RGB));

        final INDArray image = loader.asMatrix(imageFile);
        logger.info("image.shape: {}", image.shape());

        final ImagePreProcessingScaler scaler = new ImagePreProcessingScaler(0, 1);
        scaler.transform(image);

        final File f = new File("last (1).onnx");
        OnnxRuntimeRunner onnxRuntimeRunner = OnnxRuntimeRunner.builder().modelUri(
                f.getAbsolutePath()).build();

        Map<String, INDArray> inputs = new LinkedHashMap<>();
        inputs.put("images", image);
        //inputs.put("input", image);

        Map<String, INDArray> results = onnxRuntimeRunner.exec(inputs);
        logger.info("keySet: {}", results.keySet());
        ///List<DetectedObject> objs = yout.getPredictedObjects(results, detectionThreshold);

        INDArray out = results.get("output0");

        System.out.println("----");
        logger.info("out.shape: {}", out.shape());
        final int boxNb = (int) out.shape()[2];
        logger.info("boxNb: {}", boxNb);
        // 1:     image
        // 140:   xc, yc, w, h, c0, c1, ..., c135
        // 80724: boxes values

        System.out.println("----");
        int imgIdx = 0;
        INDArray img = out.get(NDArrayIndex.point(imgIdx), NDArrayIndex.all());
        logger.info("img: \n{}", img);
        logger.info("imgRank: {}", img.rank());
        logger.info("imgShape: {}", img.shape());
        logger.info("imgLength: {}", img.length());

        final double dt = 0.5; // Detection threshold

        for (Cls c : Cls.values()) {
            final int row = c.ordinal() + 4;
            final INDArray values = img.get(NDArrayIndex.point(row), NDArrayIndex.all());
            final StringBuilder sb = new StringBuilder();

            for (int i = 0; i < boxNb; i++) {
                final double val = values.getDouble(i);
                if (val >= dt) {
                    sb.append('X');
                }
            }

            if (sb.length() > 0) {
                System.out.println(String.format("%40s %s", c, sb));
            }
        }

        for (Cls c : new Cls[] { Cls.brace }) {
            final int row = c.ordinal() + 4;
            final INDArray values = img.get(NDArrayIndex.point(row), NDArrayIndex.all());

            for (int i = 0; i < boxNb; i++) {
                final double val = values.getDouble(i);
                if (val >= dt) {
                    // Convert from xc,yc,w,h to x,y,w,h
                    double xc = img.getDouble(0, i);
                    double yc = img.getDouble(1, i);
                    double w = img.getDouble(2, i);
                    double h = img.getDouble(3, i);
                    double x = xc - w / 2;
                    double y = yc - h / 2;

                    // Resize according to original image size
                    x = x * wRatio;
                    y = y * hRatio;
                    w = w * wRatio;
                    h = h * hRatio;
                    System.out.println(
                            String.format(
                                    "x: %.0f y: %.0f w: %.0f h: %.0f conf: %.5f",
                                    x,
                                    y,
                                    w,
                                    h,
                                    val));
                }
            }
        }
    }

